    if gaz_pages:
        occ.append(O("AR54-GAZ", pages=gaz_pages, anchor=gaz_anchor or doc_anchor))
    occ += (extra_occ or [])
    occ += [O("MML-AR-DOC1", anchor=docs_anchor or doc_anchor, from_line=8830), O("MML-AR-DOC", anchor=docs_anchor or doc_anchor, from_line=5495)]
    return F(fid, instrument="Army Rules, 1954", part=part, number=number, title=title, prescribing_provision=prov,
             requirement_quote=quote, authority=authority, status=status, applicability=applic, signatory=signatory,
             competent_authority=signatory, dependencies="Confirmation/order of competent authority as recited in the warrant",
             companions="Original warrant to be returned where the form so requires (as printed)", version_history=vh,
             supersession=sup, uncertainties=unc + COMMON_AR_UNC, field_scope="RECITALS_BLANKS_AND_NOTES", fields=fields, occurrences=occ)


